                    this._barRow(window.mySimulation.t('level2a_label'), Math.round(adjL2a), maxH, '#45b7d1', Math.round(adjL2a)) +
                    this._barRow(window.mySimulation.t('level2b_label'), Math.round(adjL2b), maxH, '#f39c12', Math.round(adjL2b));
            }

            var fundEl = document.getElementById('fundingBreakdown');
            if (fundEl) {
                var maxF = 20000;
                var retDep = B.retailDeposits - B.retailDeposits * (ds.depositRunPct || 0) / 100;
                var worF = B.wholesaleFunding * (1 - (ds.wholesaleFreezePct || 0) / 100);
                fundEl.innerHTML =
                    this._barRow(window.mySimulation.t('retail_dep_label'), Math.round(retDep), maxF, '#4ecdc4', Math.round(retDep)) +
                    this._barRow(window.mySimulation.t('wholesale_label'), Math.round(worF), maxF, '#e74c3c', Math.round(worF)) +
                    this._barRow(window.mySimulation.t('repo_label'), B.repoFunding, maxF, '#f39c12', B.repoFunding) +
                    this._barRow(window.mySimulation.t('interbank_label'), B.interbankLiab, maxF, '#45b7d1', B.interbankLiab);
            }
        }

        _barRow(label, value, maxVal, color, displayVal) {
            var pct = Math.min(100, Math.round(value / maxVal * 100));
            return '<div class="liquidity-sim-bar-row">' +
                '<span class="liquidity-sim-bar-label">' + label + '</span>' +
                '<div class="liquidity-sim-bar-track"><div class="liquidity-sim-bar-fill" style="width:' + pct + '%;background:' + color + ';"></div></div>' +
                '<span class="liquidity-sim-bar-value">€' + Math.round(displayVal).toLocaleString() + 'M</span>' +
                '</div>';
        }

        _recalcMetrics(ds) {
            var B = this.BANK;
            var hqla = B.adjHQLA;
            var outflows = B.baseOutflows;
            var asf = B.baseASF;
            var rsf = B.baseRSF;

            if (ds.depositRunPct > 0) {
                outflows += B.retailDeposits * ds.depositRunPct / 100;
                asf -= 0.9 * B.retailDeposits * ds.depositRunPct / 100;
            }
            if (ds.wholesaleFreezePct > 0) {
                outflows += B.wholesaleFunding * ds.wholesaleFreezePct / 100;
                asf -= 0.5 * B.wholesaleFunding * ds.wholesaleFreezePct / 100;
            }
            if (ds.collateralShockPct > 0) {
                var newL2a = B.hqlaL2a * (1 - (0.15 + ds.collateralShockPct / 100));
                var newL2b = Math.max(0, B.hqlaL2b * (1 - (0.50 + ds.collateralShockPct / 100)));
                hqla = B.hqlaL1 + newL2a + newL2b;
                outflows += (B.adjHQLA - hqla) * 0.3;
            }
            if (ds.ratingNotches > 0) {
                outflows += 1500 * ds.ratingNotches;
                asf -= 500 * ds.ratingNotches;
            }

            if (ds.amplificationPct > 100) {
                var amp = ds.amplificationPct / 100;
                var outflowDelta = outflows - B.baseOutflows;
                var hqlaDelta = B.adjHQLA - hqla;
                var asfDelta = B.baseASF - asf;
                outflows = B.baseOutflows + outflowDelta * amp;
                hqla = B.adjHQLA - hqlaDelta * amp;
                asf = B.baseASF - asfDelta * amp;
            }

            if (ds.contingencyAction === 1) {
                hqla += 2000;
            } else if (ds.contingencyAction === 2) {
                hqla += 3000;
                outflows -= 1000;
            } else if (ds.contingencyAction === 3) {
                outflows -= 1500;
            } else if (ds.contingencyAction === 4) {
                hqla += 4000;
            }

            hqla = Math.max(0, hqla);
            outflows = Math.max(1, outflows);
            asf = Math.max(0, asf);
            rsf = Math.max(1, rsf);

            ds.currentHQLA = Math.round(hqla);
            ds.currentOutflows = Math.round(outflows);
            ds.currentASF = Math.round(asf);
            ds.currentRSF = rsf;
            ds.lcr = Math.round(hqla / outflows * 100);
            ds.nsfr = Math.round(asf / rsf * 100);
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var input = document.getElementById('actionInput');
            if (input) {
                decisions.action = parseFloat(input.value);
            }
            if (decisions.action === undefined || isNaN(decisions.action)) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('action_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var round = this.ROUNDS[Math.min(period - 1, this.ROUNDS.length - 1)];
            var score = 0;

            switch(period) {
                case 1:
                    score = (d.action === 2) ? 15 : (d.action === 4) ? 12 : (d.action === 1) ? 8 : 6;
                    break;
                case 2:
                    ds.depositRunPct = d.action;
                    score = 10;
                    break;
                case 3:
                    ds.wholesaleFreezePct = d.action;
                    score = 10;
                    break;
                case 4:
                    ds.collateralShockPct = d.action;
                    score = 10;
                    break;
                case 5:
                    ds.ratingNotches = d.action;
                    score = 10;
                    break;
                case 6:
                    ds.amplificationPct = d.action;
                    this._recalcMetrics(ds);
                    var combinedLcr = ds.lcr;
                    score = (combinedLcr < 50) ? 15 : (combinedLcr < 75) ? 12 : 8;
                    break;
                case 7:
                    ds.contingencyAction = d.action;
                    this._recalcMetrics(ds);
                    score = (ds.lcr >= 90) ? 18 : (ds.lcr >= 70) ? 14 : 10;
                    break;
                case 8:
                    score = (d.action === 3) ? 15 : (d.action === 1) ? 13 : (d.action === 4) ? 12 : 10;
                    break;
            }

            this._recalcMetrics(ds);

            ds.totalScore += score;
            ds.lcrHistory.push(ds.lcr);
            ds.nsfrHistory.push(ds.nsfr);
            ds.scoreHistory.push(score);

            // v1.1.0: expose a 0-100 overall (score / performance.overallScore) for the
            // grading/reporting layer, tied to the sim's own totalScore tiers.
            var _overall = Math.max(0, Math.min(100, Math.round(ds.totalScore)));
            var _rating = 'Needs Improvement';
            if (ds.totalScore >= 85) _rating = 'Excellent';
            else if (ds.totalScore >= 70) _rating = 'Good';
            else if (ds.totalScore >= 55) _rating = 'Developing';
            ds.score = _overall;
            ds.performance = { overallScore: _overall, rating: _rating, rawScore: ds.totalScore };

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
                self._updateDashboard(ds);
            })(state.currentPeriod + 1), 500);

            return {
                period: period,
                scenario: window.mySimulation.t(round.phaseShortKey),
                actionValue: d.action,
                lcrAfter: ds.lcr,
                nsfrAfter: ds.nsfr,
                hqlaAfter: ds.currentHQLA,
                outflowsAfter: ds.currentOutflows,
                phaseScore: score,
                totalScore: ds.totalScore
            };
        }

