        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.phaseScore || 0 : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var lcrValues = history.map(function(r) { return r.results ? r.results.lcrAfter || 0 : 0; });
            var minLcr = Math.min.apply(null, lcrValues);
            var finalLcr = lcrValues[lcrValues.length - 1] || 0;

            var performance = window.mySimulation.t('perf_needs_improvement');
            if (totalScore >= 85) performance = window.mySimulation.t('perf_excellent');
            else if (totalScore >= 70) performance = window.mySimulation.t('perf_good');
            else if (totalScore >= 55) performance = window.mySimulation.t('perf_developing');

            var insights = [];
            if (minLcr < 60) insights.push(window.mySimulation.t('insight_critical_lcr'));
            if (minLcr < 100 && finalLcr >= 100) insights.push(window.mySimulation.t('insight_contingency_success'));
            if (minLcr >= 100) insights.push(window.mySimulation.t('insight_maintained_compliance'));
            if (totalScore >= 85) insights.push(window.mySimulation.t('insight_strong_performance'));
            if (totalScore < 55) insights.push(window.mySimulation.t('insight_review_framework'));

            var overallScore = Math.max(0, Math.min(100, Math.round(totalScore)));
            return {
                totalScore: totalScore,
                overallScore: overallScore,
                score: overallScore,
                minLcr: minLcr,
                finalLcr: finalLcr,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var lcr = results.lcrAfter || 0;
            if (lcr < 60) return window.mySimulation.t('hint_critical');
            if (lcr < 80) return window.mySimulation.t('hint_severe');
            if (lcr < 100) return window.mySimulation.t('hint_warning');
            if (lcr >= 110) return window.mySimulation.t('hint_stable');
            return null;
        }

